 10	/**
 11	 * Borrower Messages Page
 12	 * 
 13	 * A dedicated interface for borrowers to communicate with loan officers and other lenders.
 14	 * Provides conversation management and messaging capabilities.
 15	 */
 16	const BorrowerMessages = () => {
 17	 // State for user data
 18	 const [userData, setUserData] = useState(null);
 19	 // State for loading
 20	 const [isLoading, setIsLoading] = useState(true);
 21	 // State for lender data
 22	 const [lender, setLender] = useState(null);
 23	 // State for messages
 24	 const [messages, setMessages] = useState([]);
 25	 // State for loading messages
 26	 const [loadingMessages, setLoadingMessages] = useState(false);
 27	 // State for message input
 28	 const [messageInput, setMessageInput] = useState('');
 29	 // State for sending message
 30	 const [sendingMessage, setSendingMessage] = useState(false);
 31	 // State for file attachments
 32	 const [attachments, setAttachments] = useState([]);
 33	 // State for uploading status
 34	 const [uploading, setUploading] = useState(false);
 35	 
 36	 // Ref for message container to auto scroll
 37	 const messageContainerRef = useRef(null);
 38	 // Ref for file input
 39	 const fileInputRef = useRef(null);
 40	 
 41	 // Load user data when component mounts
 42	 useEffect(() => {
 43	 fetchUserData();
 44	 }, []);
 45	 
 46	 // Auto scroll to bottom when messages change
 47	 useEffect(() => {
 48	 if (messageContainerRef.current) {
 49	 messageContainerRef.current.scrollTop = messageContainerRef.current.scrollHeight;
 50	 }
 51	 }, [messages]);
 52	 
 53	 // Initialize socket connection
 54	 useEffect(() => {
 55	 if (userData?.data?.user?._id) {
 56	 // Connect to socket
 57	 const socket = socketService.connect();
 58	 
 59	 // Join user's room
 60	 socketService.joinRoom(userData.data.user._id);
 61	 console.log('Borrower Messages: Joined room', userData.data.user._id);
 62	 
 63	 // Handle direct message events
 64	 const handleNewMessage = (message) => {
 65	 console.log('Borrower Messages: New message received', message);
 66	 
 67	 // Check if this message belongs to the current conversation or is a new message
 68	 if ((message.borrower && lender?.borrowerId && message.borrower === lender.borrowerId) || 
 69	 (message.sender && message.sender === 'lender')) {
 70	 setMessages((prevMessages) => {
 71	 // Check if message already exists to prevent duplicates
 72	 const exists = prevMessages.some(m => m._id === message._id);
 73	 if (!exists) {
 74	 // Show notification for new messages
 75	 toast.success('New message received');
 76	 return [...prevMessages, message];
 77	 }
 78	 return prevMessages;
 79	 });
 80	 
 81	 // Scroll to bottom when new message arrives
 82	 setTimeout(() => {
 83	 if (messageContainerRef.current) {
 84	 messageContainerRef.current.scrollTop = messageContainerRef.current.scrollHeight;
 85	 }
 86	 }, 100);
 87	 }
 88	 };
 89	 
 90	 // Register direct event listeners
 91	 socket.on('receive_message', handleNewMessage);
 92	 socket.on('new_lender_message', handleNewMessage);
 93	 
 94	 // Clean up on unmount
 95	 return () => {
 96	 socket.off('receive_message', handleNewMessage);
 97	 socket.off('new_lender_message', handleNewMessage);
 98	 };
 99	 }
 100	 }, [userData?.data?.user?._id, lender?.borrowerId]);
 101	 
 102	 // Fetch user data
 103	 const fetchUserData = async () => {
 104	 setIsLoading(true);
 105	 try {
 106	 // Get the user profile from the server
 107	 const response = await api.get('/users/me');
 108	 setUserData(response.data);
 109	 
 110	 // Get borrower information
 111	 const borrowerResponse = await api.get('/borrower/profile');
 112	 // console.log(borrowerResponse.data);
 113	 const borrowerData = borrowerResponse.data;
 114	 // console.log("borrowerData", borrowerData);
 115	 
 116	 // Fetch lender information
 117	 if (borrowerData && borrowerData.data.lender) {
 118	 try {
 119	 console.log("borrowerData.lender", borrowerData.data.lender);
 120	 const lenderResponse = await api.get(`/lenders/${borrowerData.data.lender}`);
 121	 console.log("lenderResponse", lenderResponse.data);
 122	 setLender({
 123	 ...lenderResponse.data,
 124	 borrowerId: borrowerData.data._id
 125	 });
 126	 
 127	 // Fetch messages between borrower and lender
 128	 fetchMessages(borrowerData.data._id);
 129	 } catch (error) {
 130	 console.error('Error fetching lender data:', error);
 131	 toast.error('Failed to load lender data. Please try again later.');
 132	 }
 133	 }
 134	 } catch (error) {
 135	 console.error('Error fetching user data:', error);
 136	 toast.error('Failed to load user data. Please try again later.');
 137	 } finally {
 138	 setIsLoading(false);
 139	 }
 140	 };
 141	 
 142	 // Fetch messages between borrower and lender
 143	 const fetchMessages = async (borrowerId) => {
 144	 setLoadingMessages(true);
 145	 try {
 146	 const result = await MessageService.getMessages(borrowerId);
 147	 if (result.success) {
 148	 setMessages(result.data);
 149	 } else {
 150	 toast.error('Failed to load messages');
 151	 }
 152	 } catch (error) {
 153	 console.error('Error fetching messages:', error);
 154	 toast.error('Failed to load messages');
 155	 } finally {
 156	 setLoadingMessages(false);
 157	 }
 158	 };
 159	 
 160	 // Handle file selection
 161	 const handleFileChange = (e) => {
 162	 if (e.target.files) {
 163	 const newFiles = Array.from(e.target.files);
 164	 
 165	 // Filter by image files only
 166	 const imageFiles = newFiles.filter(file => file.type.startsWith('image/'));
 167	 
 168	 if (imageFiles.length !== newFiles.length) {
 169	 toast.error('Only image files are allowed');
 170	 }
 171	 
 172	 // Limit to 5 images at a time
 173	 if (attachments.length + imageFiles.length > 5) {
 174	 toast.error('Maximum 5 images allowed per message');
 175	 return;
 176	 }
 177	 
 178	 // Add preview for selected images
 179	 const filesWithPreview = imageFiles.map(file => ({
 180	 file,
 181	 preview: URL.createObjectURL(file)
 182	 }));
 183	 
 184	 setAttachments([...attachments, ...filesWithPreview]);
 185	 }
 186	 };
 187	 
 188	 // Remove an attachment
 189	 const removeAttachment = (index) => {
 190	 const newAttachments = [...attachments];
 191	 
 192	 // Revoke object URL to prevent memory leaks
 193	 URL.revokeObjectURL(newAttachments[index].preview);
 194	 
 195	 newAttachments.splice(index, 1);
 196	 setAttachments(newAttachments);
 197	 };
 198	 
 199	 // Open file selector
 200	 const openFileSelector = () => {
 201	 if (fileInputRef.current) {
 202	 fileInputRef.current.click();
 203	 }
 204	 };
 205	 
 206	 // Send a message to the lender
 207	 const sendMessage = async () => {
 208	 if ((!messageInput.trim() && attachments.length === 0) || !lender) return;
 209	 
 210	 setSendingMessage(true);
 211	 try {
 212	 // Extract files from the attachments
 213	 const files = attachments.map(attachment => attachment.file);
 214	 
 215	 const result = await MessageService.sendMessage(lender.borrowerId, messageInput, files);
 216	 if (result.success) {
 217	 setMessages([...messages, result.data]);
 218	 setMessageInput('');
 219	 setAttachments([]);
 220	 
 221	 // Emit socket event for real-time updates
 222	 socketService.sendMessage(result.data);
 223	 
 224	 toast.success('Message sent');
 225	 } else {
 226	 toast.error('Failed to send message');
 227	 }
 228	 } catch (error) {
 229	 console.error('Error sending message:', error);
 230	 toast.error('Failed to send message');
 231	 } finally {
 232	 setSendingMessage(false);
 233	 }
 234	 };
 235	
 236	 // Get the sender's display name
 237	 const getSenderName = (message) => {
 238	 if (message.sender._id === userData?._id) {
 239	 return 'You';
 240	 }
 241	 return `${message.sender.firstName || ''} ${message.sender.lastName || ''}`.trim() || message.sender.email || 'Loan Officer';
 242	 };
 243	
 244	 // Format message time
 245	 const formatMessageTime = (timestamp) => {
 246	 return new Date(timestamp).toLocaleTimeString([], {
 247	 hour: '2-digit',
 248	 minute: '2-digit'
 249	 });
 250	 };
 251	
 252	 // Check if the message has an image attachment
 253	 const hasImageAttachment = (message) => {
 254	 return message.attachments && message.attachments.length > 0;
 255	 };
 256	
 257	 // Get image URL with proper base path
 258	 const getImageUrl = (attachment) => {
 259	 const baseUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:5000';
 260	 
 261	 // Make sure we don't duplicate the base URL if it's already included
 262	 if (attachment.url.startsWith('http')) {
 263	 return attachment.url;
 264	 }
 265	 
 266	 // Extract the filename from the URL path
 267	 const urlParts = attachment.url.split('/');
 268	 const filename = urlParts[urlParts.length - 1];
 269	 
 270	 // Use our proxy route to avoid CORS issues
 271	 return `${baseUrl}/api/image-proxy/${filename}`;
 272	 };
 273	 
 274	 return (
 275	 <ProtectedRoute allowedRoles={['borrower']}>
 276	 <MainLayout>
 277	 <div className="py-6 h-full flex flex-col">
 278	 <div className="px-4 sm:px-6 md:px-8">
