 1	import React, { useState, useEffect, useRef } from 'react';
 2	import { toast } from 'react-hot-toast';
 3	import MainLayout from '../../components/layout/MainLayout';
 4	import ProtectedRoute from '../../components/auth/ProtectedRoute';
 5	import { MessageService } from '../../services';
 6	import api from '../../services/api';
 7	import { useRouter } from 'next/router';
 8	import { ImageViewer } from '../../components/common';
 9	import socketService from '../../services/socket.service';
 10	
 11	/**
 12	 * Lender Messages Page
 13	 * 
 14	 * A dedicated interface for lenders to communicate with borrowers and other team members.
 15	 * Provides conversation management, messaging capabilities, and integration with loan information.
 16	 */
 17	const LenderMessages = () => {
 18	 const router = useRouter();
 19	 
 20	 // State for user data
 21	 const [userData, setUserData] = useState(null);
 22	 // State for loading
 23	 const [isLoading, setIsLoading] = useState(true);
 24	 // State for conversations
 25	 const [conversations, setConversations] = useState([]);
 26	 // State for loading conversations
 27	 const [loadingConversations, setLoadingConversations] = useState(false);
 28	 // State for selected borrower
 29	 const [selectedBorrower, setSelectedBorrower] = useState(null);
 30	 // State for messages
 31	 const [messages, setMessages] = useState([]);
 32	 // State for loading messages
 33	 const [loadingMessages, setLoadingMessages] = useState(false);
 34	 // State for message input
 35	 const [messageInput, setMessageInput] = useState('');
 36	 // State for sending message
 37	 const [sendingMessage, setSendingMessage] = useState(false);
 38	 // State for file attachments
 39	 const [attachments, setAttachments] = useState([]);
 40	 // State for uploading status
 41	 const [uploading, setUploading] = useState(false);
 42	 
 43	 // Ref for message container to auto scroll
 44	 const messageContainerRef = useRef(null);
 45	 // Ref for file input
 46	 const fileInputRef = useRef(null);
 47	 
 48	 // Load user data when component mounts
 49	 useEffect(() => {
 50	 // Get borrowerId from URL if available
 51	 const { borrowerId } = router.query;
 52	 
 53	 fetchUserData();
 54	 
 55	 // If borrowerId is provided, select that borrower
 56	 if (borrowerId) {
 57	 // We'll set this after loading conversations
 58	 localStorage.setItem('selectedBorrowerId', borrowerId);
 59	 }
 60	 }, [router.query]);
 61	 
 62	 // Auto scroll to bottom when messages change
 63	 useEffect(() => {
 64	 if (messageContainerRef.current) {
 65	 messageContainerRef.current.scrollTop = messageContainerRef.current.scrollHeight;
 66	 }
 67	 }, [messages]);
 68	 
 69	 // Initialize socket connection
 70	 useEffect(() => {
 71	 if (userData?.data?.user?._id) {
 72	 // Connect to socket
 73	 const socket = socketService.connect();
 74	 
 75	 // Join user's room
 76	 socketService.joinRoom(userData.data.user._id);
 77	 
 78	 // Add message listener
 79	 socketService.addMessageListener('lender-messages', (message) => {
 80	 // Check if this message belongs to the current conversation
 81	 if (selectedBorrower && message.borrower === selectedBorrower._id) {
 82	 setMessages((prevMessages) => {
 83	 // Check if message already exists to prevent duplicates
 84	 const exists = prevMessages.some(m => m._id === message._id);
 85	 if (!exists) {
 86	 return [...prevMessages, message];
 87	 }
 88	 return prevMessages;
 89	 });
 90	 
 91	 // Scroll to bottom when new message arrives
 92	 setTimeout(() => {
 93	 if (messageContainerRef.current) {
 94	 messageContainerRef.current.scrollTop = messageContainerRef.current.scrollHeight;
 95	 }
 96	 }, 100);
 97	 }
 98	 
 99	 // Update conversations list with latest message
 100	 setConversations(prevConversations => 
 101	 prevConversations.map(conv => 
 102	 conv.borrower._id === message.borrower 
 103	 ? { 
 104	 ...conv, 
 105	 latestMessage: message 
 106	 } 
 107	 : conv
 108	 )
 109	 );
 110	 });
 111	 
 112	 // Clean up on unmount
 113	 return () => {
 114	 socketService.removeMessageListener('lender-messages');
 115	 };
 116	 }
 117	 }, [userData?.data?.user?._id, selectedBorrower]);
 118	 
 119	 // Fetch user data
 120	 const fetchUserData = async () => {
 121	 console.log("fetchUserData");
 122	 setIsLoading(true);
 123	 try {
 124	 // Get the user profile from the server
 125	 const response = await api.get('/users/me');
 126	 console.log("response", response.data);
 127	 setUserData(response.data);
 128	 
 129	 // Fetch conversations
 130	 fetchConversations();
 131	 } catch (error) {
 132	 console.error('Error fetching user data:', error);
 133	 toast.error('Failed to load user data. Please try again later.');
 134	 setIsLoading(false);
 135	 }
 136	 };
 137	 
 138	 // Fetch all conversations for the lender
 139	 const fetchConversations = async () => {
 140	 setLoadingConversations(true);
 141	 try {
 142	 const result = await MessageService.getConversations();
 143	 if (result.success) {
 144	 setConversations(result.data);
 145	 setIsLoading(false);
 146	 
 147	 // If there are conversations and selectedBorrowerId exists in localStorage, select that borrower
 148	 if (result.data.length > 0) {
 149	 const savedBorrowerId = localStorage.getItem('selectedBorrowerId');
 150	 if (savedBorrowerId) {
 151	 const found = result.data.find(
 152	 conv => conv.borrower?._id === savedBorrowerId
 153	 );
 154	 
 155	 if (found) {
 156	 selectBorrower(found.borrower);
 157	 localStorage.removeItem('selectedBorrowerId');
 158	 } else {
 159	 // If no matching borrower found, select the first one
 160	 selectBorrower(result.data[0].borrower);
 161	 }
 162	 } else {
 163	 // Select first borrower by default
 164	 selectBorrower(result.data[0].borrower);
 165	 }
 166	 }
 167	 } else {
 168	 toast.error('Failed to load conversations');
 169	 setIsLoading(false);
 170	 }
 171	 } catch (error) {
 172	 console.error('Error fetching conversations:', error);
 173	 toast.error('Failed to load conversations');
 174	 setIsLoading(false);
 175	 } finally {
 176	 setLoadingConversations(false);
 177	 }
 178	 };
 179	 
 180	 // Select a borrower to chat with
 181	 const selectBorrower = (borrower) => {
 182	 setSelectedBorrower(borrower);
 183	 
 184	 if (borrower) {
 185	 fetchMessages(borrower._id);
 186	 } else {
 187	 setMessages([]);
 188	 }
 189	 };
 190	 
 191	 // Fetch messages between lender and selected borrower
 192	 const fetchMessages = async (borrowerId) => {
 193	 setLoadingMessages(true);
 194	 try {
 195	 const result = await MessageService.getMessages(borrowerId);
 196	 if (result.success) {
 197	 setMessages(result.data);
 198	 
 199	 // Update unread count in conversations
 200	 setConversations(prevConversations => 
 201	 prevConversations.map(conv => 
 202	 conv.borrower._id === borrowerId 
 203	 ? { ...conv, unreadCount: 0 } 
 204	 : conv
 205	 )
 206	 );
 207	 } else {
 208	 toast.error('Failed to load messages');
 209	 }
 210	 } catch (error) {
 211	 console.error('Error fetching messages:', error);
 212	 toast.error('Failed to load messages');
 213	 } finally {
 214	 setLoadingMessages(false);
 215	 }
 216	 };
 217	 
 218	 // Handle file selection
 219	 const handleFileChange = (e) => {
 220	 if (e.target.files) {
 221	 const newFiles = Array.from(e.target.files);
 222	 
 223	 // Filter by image files only
 224	 const imageFiles = newFiles.filter(file => file.type.startsWith('image/'));
 225	 
 226	 if (imageFiles.length !== newFiles.length) {
 227	 toast.error('Only image files are allowed');
 228	 }
 229	 
 230	 // Limit to 5 images at a time
 231	 if (attachments.length + imageFiles.length > 5) {
 232	 toast.error('Maximum 5 images allowed per message');
 233	 return;
 234	 }
 235	 
 236	 // Add preview for selected images
 237	 const filesWithPreview = imageFiles.map(file => ({
 238	 file,
 239	 preview: URL.createObjectURL(file)
 240	 }));
 241	 
 242	 setAttachments([...attachments, ...filesWithPreview]);
 243	 }
 244	 };
 245	 
 246	 // Remove an attachment
 247	 const removeAttachment = (index) => {
 248	 const newAttachments = [...attachments];
 249	 
 250	 // Revoke object URL to prevent memory leaks
 251	 URL.revokeObjectURL(newAttachments[index].preview);
 252	 
 253	 newAttachments.splice(index, 1);
 254	 setAttachments(newAttachments);
 255	 };
 256	 
 257	 // Open file selector
 258	 const openFileSelector = () => {
 259	 if (fileInputRef.current) {
 260	 fileInputRef.current.click();
 261	 }
 262	 };
 263	 
 264	 // Send a message to the selected borrower
 265	 const sendMessage = async () => {
 266	 if ((!messageInput.trim() && attachments.length === 0) || !selectedBorrower) return;
 267	 
 268	 setSendingMessage(true);
 269	 try {
 270	 // Extract files from the attachments
 271	 const files = attachments.map(attachment => attachment.file);
 272	 
 273	 const result = await MessageService.sendMessage(selectedBorrower._id, messageInput, files);
 274	 if (result.success) {
 275	 setMessages([...messages, result.data]);
 276	 setMessageInput('');
 277	 setAttachments([]);
 278	 
 279	 // Emit socket event for real-time updates
 280	 socketService.sendMessage(result.data);
 281	 
 282	 // Update latest message in conversations
 283	 setConversations(prevConversations => 
 284	 prevConversations.map(conv => 
 285	 conv.borrower._id === selectedBorrower._id 
 286	 ? { 
 287	 ...conv, 
 288	 latestMessage: result.data 
 289	 } 
 290	 : conv
 291	 )
 292	 );
 293	 } else {
 294	 toast.error('Failed to send message');
 295	 }
 296	 } catch (error) {
 297	 console.error('Error sending message:', error);
 298	 toast.error('Failed to send message');
 299	 } finally {
 300	 setSendingMessage(false);
 301	 }
 302	 };
 303	 
 304	 // Get the sender's display name
 305	 const getSenderName = (message) => {
 306	 if (message.sender._id === userData?._id) {
 307	 return 'You';
 308	 }
 309	 return `${message.sender.firstName || ''} ${message.sender.lastName || ''}`.trim() || message.sender.email || 'Unknown';
 310	 };
